409	    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat &&
410	                output.is_contiguous(), "contiguous CUDA FP32 output required");
411	    TORCH_CHECK(output.dim() == 3 && output.size(1) == output.size(2),
412	                "square matrix batches required");
