  1351	template <int N>
  1352	__global__ void fused_left_looking_tile(
  1353	    const float* __restrict__ input,
  1354	    float* __restrict__ output
  1355	) {
  1356	    constexpr int LD = N + 1;
  1357	    extern __shared__ float tile[];
  1358	    const int tid = threadIdx.x;
  1359	    const long long base = static_cast<long long>(blockIdx.x) * N * N;
  1360	    const float* src = input + base;
  1361	    float* dst = output + base;
  1362	
  1363	    for (int index = tid; index < N * N; index += blockDim.x) {
  1364	        const int row = index / N;
  1365	        const int col = index - row * N;
  1366	        tile[row * LD + col] = row >= col ? src[index] : 0.0f;
  1367	    }
  1368	    __syncthreads();
  1369	
  1370	    for (int k = 0; k < N; ++k) {
  1371	        if (tid == 0) {
  1372	            float diagonal = tile[k * LD + k];
  1373	            for (int j = 0; j < k; ++j) {
  1374	                const float value = tile[k * LD + j];
  1375	                diagonal = fmaf(-value, value, diagonal);
  1376	            }
  1377	            tile[k * LD + k] = sqrtf(fmaxf(diagonal, 1.0e-30f));
  1378	        }
  1379	        __syncthreads();
  1380	
  1381	        const float diagonal = tile[k * LD + k];
  1382	        for (int row = k + 1 + tid; row < N; row += blockDim.x) {
  1383	            float value = tile[row * LD + k];
  1384	            for (int j = 0; j < k; ++j) {
  1385	                value = fmaf(-tile[row * LD + j], tile[k * LD + j], value);
  1386	            }
  1387	            tile[row * LD + k] = value / diagonal;
  1388	        }
  1389	        __syncthreads();
  1390	    }
  1391	
  1392	    for (int index = tid; index < N * N; index += blockDim.x) {
  1393	        const int row = index / N;
  1394	        const int col = index - row * N;
  1395	        dst[index] = tile[row * LD + col];
  1396	    }
  1397	}
