  1399	template <int K>
  1400	__device__ __forceinline__ void register_cholesky_step_32(
  1401	    float (&row_values)[32],
  1402	    int lane
  1403	) {
  1404	    float value = row_values[K];
  1405	    #pragma unroll
  1406	    for (int j = 0; j < K; ++j) {
  1407	        const float pivot = __shfl_sync(0xffffffff, row_values[j], K);
  1408	        if (lane >= K) {
  1409	            value = fmaf(-row_values[j], pivot, value);
  1410	        }
  1411	    }
  1412	
  1413	    float inverse = 0.0f;
  1414	    if (lane == K) {
  1415	        value = sqrtf(fmaxf(value, 1.0e-30f));
  1416	        row_values[K] = value;
  1417	        inverse = 1.0f / value;
  1418	    }
  1419	    inverse = __shfl_sync(0xffffffff, inverse, K);
  1420	    if (lane > K) {
  1421	        row_values[K] = value * inverse;
  1422	    }
